toolArgs.file_text:
.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #fff;
}

.area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e8e8ed;
    flex-shrink: 0;
}

.area-header h2 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
    color: #1a1a2e;
}

.area-header p {
    margin: 2px 0 0;
    font-size: 0.82rem;
    color: #777;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.load-more {
    text-align: center;
    padding: 8px;
}

.load-more-btn {
    background: none;
    border: 1px solid #dde1e6;
    color: #1264a3;
    padding: 6px 16px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.82rem;
    font-weight: 600;
}

.load-more-btn:hover:not(:disabled) {
    background-color: #f0f4fa;
}

.load-more-btn:disabled {
    color: #999;
    cursor: default;
}

.message-input-area {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #e8e8ed;
    flex-shrink: 0;
}

.message-textarea {
    flex: 1;
    resize: none;
    border: 1px solid #dde1e6;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    min-height: 40px;
    max-height: 120px;
}

.message-textarea:focus {
    border-color: #1264a3;
    box-shadow: 0 0 0 1px #1264a3;
}

.send-btn {
    background-color: #1264a3;
    color: #fff;
    border: none;
    padding: 10px 20px;
    border-radius: 8px;
    font-weight: 600;
    font-size: 0.88rem;
    cursor: pointer;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background-color: #0e5289;
}

.send-btn:disabled {
    background-color: #a0c4e8;
    cursor: default;
}

