.chat-layout {
    height: 100vh;
    width: 100vw;
    overflow: hidden;
    margin: 0;
    padding: 0;
}

@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_5810808742cc4207abac5286d8b378f9.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="_channels"
                        SelectedChannelId="_selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-panel @(_isThreadOpen ? "" : "expanded")">
        @if (_selectedChannel is not null)
        {
            <MessageArea ChannelName="@_selectedChannel.Name"
                         ChannelDescription="@_selectedChannel.Description"
                         Messages="_messages"
                         ThreadReplyCounts="_threadReplyCounts"
                         HasMoreMessages="_hasMoreMessages"
                         IsLoadingMore="_isLoadingMore"
                         OnLoadMore="LoadMoreMessages"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage" />
        }
        else
        {
            <div class="no-channel">
                <p>Select a channel to start messaging</p>
            </div>
        }
    </div>

    @if (_isThreadOpen)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private Channel? _selectedChannel;
    private int _selectedChannelId;

    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = [];
    private bool _hasMoreMessages = true;
    private bool _isLoadingMore;
    private int _skip;

    private bool _isThreadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadMessages = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _selectedChannel = channel;
        _selectedChannelId = channel.Id;
        _skip = 0;
        _hasMoreMessages = true;
        _messages = [];
        _threadReplyCounts = [];

        CloseThreadInternal();

        var loaded = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = loaded;
        _skip = loaded.Count;
        _hasMoreMessages = loaded.Count == PageSize;

        BuildThreadReplyCounts();

        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channel list to update unread counts
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        if (_isLoadingMore || _selectedChannel is null) return;

        _isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _skip, PageSize);
        _messages.InsertRange(0, older);
        _skip += older.Count;
        _hasMoreMessages = older.Count == PageSize;
        _isLoadingMore = false;

        BuildThreadReplyCounts();
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;
        var message = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(message);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        await RefreshMessages();
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _isThreadOpen = true;
    }

    private void CloseThread() => CloseThreadInternal();

    private void CloseThreadInternal()
    {
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _selectedChannel is null) return;

        var reply = await ChatService.SendMessageAsync(
            _selectedChannel.Id, content, _threadRootMessage.Id);

        _threadMessages.Add(reply);

        // Update reply count
        _threadReplyCounts[_threadRootMessage.Id] = _threadMessages.Count;
    }

    private async Task RefreshMessages()
    {
        if (_selectedChannel is null) return;
        var refreshed = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _skip);
        _messages = refreshed;
        BuildThreadReplyCounts();
    }

    private void BuildThreadReplyCounts()
    {
        _threadReplyCounts = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }
}

